import numpy as np

def relu(x):
    return np.maximum(0, x)

def sigmoid(x):
    x = np.clip(x, -500, 500)
    return 1 / (1 + np.exp(-x))

class SmallNeuralNetwork:
    def __init__(self):
        self.W1 = np.array([
            [0.5, -0.2],
            [0.3, 0.4]
        ], dtype=float)
        self.b1 = np.array([0.1, -0.1], dtype=float)

        self.W2 = np.array([
            [0.7, -0.5]
        ], dtype=float)
        self.b2 = np.array([0.2], dtype=float)

    def forward(self, X):
        X = np.asarray(X, dtype=float)

        if X.ndim == 1:
            X = X.reshape(1, -1)

        if X.shape[1] != self.W1.shape[1]:
            raise ValueError('Unexpected number of input features.')

        Z1 = X @ self.W1.T + self.b1
        A1 = relu(Z1)

        Z2 = A1 @ self.W2.T + self.b2
        predictions = sigmoid(Z2)

        return {
            'Z1': Z1,
            'A1': A1,
            'Z2': Z2,
            'predictions': predictions
        }

model = SmallNeuralNetwork()
X = np.array([
    [1.0, 2.0],
    [0.0, 1.0],
    [2.0, -1.0]
])

result = model.forward(X)

for name, values in result.items():
    print(name, values.shape)
    print(values)
